static std::optional<bool> EvaluateEqualityExpressionResult(ETSChecker *checker, ir::Expression *left,
                                                            ir::Expression *right, checker::Type *leftType,
                                                            checker::Type *rightType)
{
    if (IsTypeError(leftType) || IsTypeError(rightType)) {
        return std::nullopt;
    }

    if (HasBigIntNonBigIntEqualityPairing(checker, leftType, rightType)) {
        return false;
    }

    leftType = checker->MaybeUnboxType(checker->GetApparentType(leftType));
    rightType = checker->MaybeUnboxType(checker->GetApparentType(rightType));
    if (leftType->IsETSEnumType() && rightType->IsETSEnumType() &&
        !checker->Relation()->IsIdenticalTo(leftType, rightType)) {
        return std::nullopt;
    }

    if (leftType->IsConstantType() && rightType->IsConstantType()) {
        return checker->Relation()->IsIdenticalTo(leftType, rightType);
    }

    if (ShouldReturnFalseForEqualityExpressionResult(checker, left, right, leftType, rightType)) {
        return false;
    }

    return std::nullopt;
}

static void MaybeLogCompileTimeEqualityWarning(ETSChecker *checker, const BinaryArithmOperands &ops,
                                               lexer::TokenType operationType, const lexer::SourcePosition &pos)
{
    ir::Expression *left = ops.expr->Left();
    ir::Expression *right = ops.expr->Right();
    auto result = EvaluateEqualityExpressionResult(checker, left, right, ops.typeL, ops.typeR);
    if (!result.has_value()) {
        return;
    }

    if (operationType == lexer::TokenType::PUNCTUATOR_NOT_EQUAL ||
        operationType == lexer::TokenType::PUNCTUATOR_NOT_STRICT_EQUAL) {
        result = !result.value();
    }

    checker->LogDiagnostic(result.value() ? diagnostic::EQUALITY_EXPRESSION_ALWAYS_TRUE
                                          : diagnostic::EQUALITY_EXPRESSION_ALWAYS_FALSE,
                           pos);
}

static Type *CheckBinaryOperatorEqual(ETSChecker *checker, BinaryArithmOperands const &ops)
{
    [[maybe_unused]] auto const [expr, typeL, typeR, reducedL, reducedR] = ops;

    ERROR_TYPE_CHECK(checker, typeL, return checker->GlobalTypeError());

    auto *const appL = checker->GetApparentType(typeL);
    auto *const appR = checker->GetApparentType(typeR);
    auto isPrimitiveLikeRef = [](Type *tp) {
        return tp->IsETSObjectType() && tp->AsETSObjectType()->IsBoxedPrimitive();
    };
    if ((appL->IsETSFunctionType() && (!appR->IsETSReferenceType() || isPrimitiveLikeRef(appR))) ||
        (appR->IsETSFunctionType() && (!appL->IsETSReferenceType() || isPrimitiveLikeRef(appL)))) {
        LogOperatorCannotBeApplied(checker, ops);
        return typeL;
    }

    if (reducedL->IsETSBooleanType() && reducedR->IsETSBooleanType()) {
        if (reducedL->IsConstantType() && reducedR->IsConstantType()) {
            return checker->GetGlobalTypesHolder()->GlobalETSBooleanBuiltinType();
        }
        if (checker->CheckIfNumeric(typeL) && checker->CheckIfNumeric(typeR) && typeL->IsETSUnboxableObject() &&
            typeR->IsETSUnboxableObject()) {
            return typeL;
        }
        return reducedL;
    }

    return HandelReferenceBinaryEquality(checker, ops);
}

// Satisfying the Chinese checker
static bool NonNumericTypesAreAppropriateForComparison(ETSChecker *checker, Type *leftType, Type *rightType)
{
    leftType = checker->MaybeUnboxType(leftType);
    rightType = checker->MaybeUnboxType(rightType);
    if (rightType->IsETSStringType() && leftType->IsETSStringType()) {
        return true;
    }
    if (leftType->IsETSEnumType() && rightType->IsETSEnumType()) {
        return checker->Relation()->IsIdenticalTo(leftType, rightType);
    }
    if ((leftType->IsETSStringEnumType() && rightType->IsETSStringType()) ||
        (leftType->IsETSStringType() && rightType->IsETSStringEnumType())) {
        return true;
    }
    if ((leftType->IsETSPrimitiveType() && rightType->IsETSNumericEnumType()) ||
        (leftType->IsETSNumericEnumType() && rightType->IsETSPrimitiveType())) {
        return true;
    }
    return false;
}

static bool IsEqualityOperator(lexer::TokenType operationType)
{
    return operationType == lexer::TokenType::PUNCTUATOR_EQUAL ||
           operationType == lexer::TokenType::PUNCTUATOR_NOT_EQUAL ||
           operationType == lexer::TokenType::PUNCTUATOR_STRICT_EQUAL ||
           operationType == lexer::TokenType::PUNCTUATOR_NOT_STRICT_EQUAL;
}

static bool HasMismatchedBooleanComparands(Type *promotedType, Type *unboxedL, Type *unboxedR)
{
    return promotedType != nullptr && unboxedL != nullptr && unboxedR != nullptr &&
           unboxedL->IsETSBooleanType() != unboxedR->IsETSBooleanType();
}

static bool CheckUnionRelationalError(ETSChecker *checker, Type *leftType, Type *rightType,
                                      const RelationalContext &ctx)
{
    if ((leftType->IsETSUnionType() || rightType->IsETSUnionType()) && !IsEqualityOperator(ctx.op)) {
        checker->LogError(diagnostic::BINOP_UNION, {}, ctx.pos);
        return true;
    }
    return false;
}

static bool CheckStringEnumBooleanConflict(ETSChecker *checker, Type *leftType, Type *rightType,
                                           const RelationalContext &ctx)
{
    auto *ubL = checker->MaybeUnboxType(leftType);
    auto *ubR = checker->MaybeUnboxType(rightType);
    if ((leftType->IsETSStringEnumType() || rightType->IsETSStringEnumType()) &&
        ((ubL && ubL->IsETSBooleanType()) || (ubR && ubR->IsETSBooleanType()))) {
        LogOperatorCannotBeApplied(checker, ctx.op, ubL ? ubL : leftType, ubR ? ubR : rightType, ctx.pos);
        return true;
    }
    return false;
}

static bool CharRelationalOperandIsValid(ETSChecker *checker, Type *leftType, Type *rightType)
{
    auto const leftUnboxed = checker->MaybeUnboxType(leftType);
    auto const rightUnboxed = checker->MaybeUnboxType(rightType);
    if (leftUnboxed == nullptr || rightUnboxed == nullptr) {
        return true;
    }
    auto const leftIsChar = leftUnboxed->IsCharType();
    auto const rightIsChar = rightUnboxed->IsCharType();
    if (!leftIsChar && !rightIsChar) {
        return true;
    }
    if (leftIsChar && rightIsChar) {
        return true;
    }
    auto const &otherUnboxed = leftIsChar ? rightUnboxed : leftUnboxed;
    // Check original type to exclude enums — enum is not a "numeric type" per spec
    auto const &otherOriginal = leftIsChar ? rightType : leftType;
