}

void ETSNumericEnumType::Cast(TypeRelation *const relation, Type *const target)
{
    if (relation->IsIdenticalTo(this, target)) {
        relation->Result(true);
        return;
    }
    if (target->HasTypeFlag(TypeFlag::ETS_NUMERIC) || target->IsBuiltinNumeric()) {
        relation->RaiseError(diagnostic::ENUM_CONVERSION_ERROR_TO, {this, target, target},
                             relation->GetNode()->Start());
        relation->Result(true);
        return;
    }
    conversion::Forbidden(relation);
}

void ETSNumericEnumType::CastTarget(TypeRelation *relation, Type *source)
{
    if (source->IsIntType() || source->IsBuiltinNumeric()) {
        relation->RaiseError(diagnostic::ENUM_CONVERSION_ERROR_FROM, {source, this}, relation->GetNode()->Start());
        relation->Result(true);
        return;
    }
    conversion::Forbidden(relation);
}

[[nodiscard]] bool ETSNumericEnumType::CheckBuiltInType(const ETSChecker *checker, ETSObjectFlags flag) const noexcept
{
    if (enumType_ != nullptr) {
        return enumType_->AsETSObjectType()->HasObjectFlag(flag);
    }

    return checker->GlobalIntBuiltinType() != nullptr;
}

[[nodiscard]] bool ETSNumericEnumType::NonAnnotedHasDouble(ETSChecker *checker) const
{
    ES2PANDA_ASSERT(EnumAnnotedType() == nullptr);
    auto underlyingUnboxed = checker->MaybeUnboxType(Underlying());
    return underlyingUnboxed->IsDoubleType() || underlyingUnboxed->IsFloatType();
}
